"""Aryan Adobe Remix — local Windows GUI; no design editing or Turn in clicks."""
import asyncio
import csv
import json
import os
from pathlib import Path
import queue
import re
import threading
import time
import tkinter as tk
from tkinter import ttk, filedialog, messagebox
from urllib.parse import urlsplit

APP_ICON_PNG = ''
BRAND_HEADER_PNG = ''

OUTPUTS = ('Published Link', 'Status', 'Stage')
ALIASES = {
    'email': ('adobe email', 'email', 'adobe id'),
    'password': ('password', 'adobe password'),
    'template': ('template link', 'template url', 'link'),
}


def adobe_url(value):
    try:
        u = urlsplit(value.strip())
        return u.scheme == 'https' and (u.hostname == 'adobe.com' or (u.hostname or '').endswith('.adobe.com')) and not u.username
    except ValueError:
        return False


def trusted_login_url(value):
    u = urlsplit(value)
    host = u.hostname or ''
    return u.scheme == 'https' and not u.username and (host == 'adobe.com' or host.endswith('.adobe.com') or host == 'adobelogin.com' or host.endswith('.adobelogin.com') or host in ('login.microsoftonline.com', 'accounts.google.com'))


def valid_published_link(value, template):
    if not isinstance(value, str) or not adobe_url(value):
        return False
    u, original = urlsplit(value.strip()), urlsplit(template.strip())
    if (u.hostname, u.path.rstrip('/')) == (original.hostname, original.path.rstrip('/')):
        return False
    return bool(re.search(r'/(page|webpage|published|publishedV2|id)/', u.path))


def read_rows(path):
    """Read first worksheet; preserve original row numbers and untouched source."""
    path = Path(path)
    if path.suffix.lower() == '.xlsx':
        from openpyxl import load_workbook
        wb = load_workbook(path, read_only=True, data_only=True)
        values = list(wb.active.values)
        wb.close()
    elif path.suffix.lower() == '.csv':
        with path.open(encoding='utf-8-sig', newline='') as f:
            values = list(csv.reader(f))
    else:
        raise ValueError('Choose an .xlsx or .csv file')
    if not values:
        raise ValueError('File is empty')
    headers = [str(v or '').strip() for v in values[0]]
    normalized = [v.lower() for v in headers]
    mapping = {}
    for key, names in ALIASES.items():
        hits = [i for i, name in enumerate(normalized) if name in names]
        if len(hits) != 1:
            raise ValueError('Exactly one column required: ' + names[0])
        mapping[key] = hits[0]
    rows = []
    for number, values_row in enumerate(values[1:], 2):
        if not any(v is not None and str(v).strip() for v in values_row):
            continue
        item = {k: str(values_row[i] if i < len(values_row) and values_row[i] is not None else '').strip() for k, i in mapping.items()}
        # Keep password whitespace as provided.
        pi = mapping['password']
        item['password'] = str(values_row[pi] if pi < len(values_row) and values_row[pi] is not None else '')
        if not item['email'] or not item['password'] or not adobe_url(item['template']):
            raise ValueError(f'Row {number}: email/password missing or template is not an HTTPS Adobe URL')
        name_columns = [i for i,h in enumerate(normalized) if h in ('name','student name','student_name','full name')]
        item['name'] = str(values_row[name_columns[0]] or '') if name_columns and name_columns[0] < len(values_row) else ''
        item['row'] = number
        rows.append(item)
    if not rows:
        raise ValueError('No student rows found')
    return headers, values, rows


class Results:
    def __init__(self, source, headers, values, events=None):
        self.events = events
        self.source = Path(source)
        self.target = self.source.with_name(self.source.stem + '_published' + self.source.suffix)
        self.journal = self.source.with_name(self.source.stem + '_progress.json')
        self.headers, self.values = headers, values
        self.records = {}
        if self.journal.exists():
            try:
                payload = json.loads(self.journal.read_text(encoding='utf-8'))
            except (ValueError, OSError):
                backup=self.journal.with_suffix('.json.bak')
                if not backup.exists():raise ValueError('Progress file is unreadable. Keep it for review; restore a valid backup before continuing.')
                payload=json.loads(backup.read_text(encoding='utf-8'))
            if payload.get('source') == str(self.source.resolve()):
                self.records = payload.get('records', {})

    def previous(self, item):
        rec = self.records.get(str(item['row']), {})
        return rec if rec.get('email') == item['email'] and rec.get('template') == item['template'] else {}

    def save(self, item, status, stage, link=''):
        self.records[str(item['row'])] = dict(name=item.get('name',''), email=item['email'], template=item['template'], status=status, stage=stage, link=link)
        tmp = self.journal.with_suffix('.json.tmp')
        tmp.write_text(json.dumps({'source': str(self.source.resolve()), 'records': self.records}, indent=2), encoding='utf-8')
        backup=self.journal.with_suffix('.json.bak')
        backup_tmp=backup.with_suffix('.bak.tmp')
        backup_tmp.write_bytes(tmp.read_bytes())
        os.replace(backup_tmp,backup)
        os.replace(tmp, self.journal)
        if self.events is not None:self.events.put(('record', (item['row'], self.records[str(item['row'])].copy())))
        self.export()

    def export(self):
        if self.source.suffix.lower() == '.xlsx':
            from openpyxl import load_workbook
            wb = load_workbook(self.source)
            ws = wb.active
            cols = {}
            for name in OUTPUTS:
                matches = [c.column for c in ws[1] if c.value == name]
                cols[name] = matches[0] if matches else ws.max_column + 1
                ws.cell(1, cols[name], name)
            for row, rec in self.records.items():
                for name, key in zip(OUTPUTS, ('link', 'status', 'stage')):
                    ws.cell(int(row), cols[name], rec[key])
            tmp = self.target.with_name(self.target.stem + '.tmp.xlsx')
            wb.save(tmp)
            wb.close()
            os.replace(tmp, self.target)
        else:
            headers = list(self.headers)
            for name in OUTPUTS:
                if name not in headers:
                    headers.append(name)
            tmp = self.target.with_suffix('.csv.tmp')
            with tmp.open('w', encoding='utf-8-sig', newline='') as f:
                writer = csv.writer(f)
                writer.writerow(headers)
                for number, value in enumerate(self.values[1:], 2):
                    row = list(value) + [''] * (len(headers) - len(value))
                    rec = self.records.get(str(number))
                    if rec:
                        for name, key in zip(OUTPUTS, ('link', 'status', 'stage')):
                            row[headers.index(name)] = rec[key]
                    writer.writerow(row)
            os.replace(tmp, self.target)


class NoRemix(Exception):
    pass


class Stopped(Exception):
    pass


class Engine:
    def __init__(self, stop, events, parallel, timeout, pause=None, retry_failed=False):
        self.pause=pause
        self.retry_failed=retry_failed
        self.stop, self.events = stop, events
        self.parallel, self.timeout = parallel, timeout
        self.clipboard_lock = asyncio.Lock()

    def check(self):
        if self.stop.is_set():
            raise Stopped()

    def log(self, row, stage):
        self.events.put(('log', f'Row {row}: {stage}'))

    async def sleep(self, seconds=0.6):
        self.check()
        await asyncio.sleep(seconds)
        self.check()

    async def visible(self, locator):
        for i in range(await locator.count()):
            loc = locator.nth(i)
            if await loc.is_visible():
                return loc
        return None

    async def button(self, page, label):
        pattern = re.compile(label, re.I)
        for root in page.frames:
            for role in ('button', 'link', 'tab', 'menuitem'):
                loc = await self.visible(root.get_by_role(role, name=pattern))
                if loc:
                    return loc
        if re.search('remix|use this template', label, re.I):
            for root in page.frames:
                loc = await self.visible(root.get_by_text(pattern, exact=True))
                if loc:
                    return loc
        return None

    async def click(self, context, label, timeout=45):
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            self.check()
            for page in reversed(context.pages):
                if page.is_closed():
                    continue
                try:
                    loc = await self.button(page, label)
                    if loc and await loc.is_enabled():
                        await loc.click(timeout=1500)
                        return page
                except Exception:
                    pass
            await self.sleep()
        raise TimeoutError('Button unavailable: ' + label)

    async def handle_login_fields(self, page, item, attempted):
        """Follow the visible provider step, allowing a bounded fresh email prompt."""
        for root in page.frames:
            if not trusted_login_url(root.url):
                continue
            if urlsplit(root.url).hostname == 'accounts.google.com' and any(part in urlsplit(root.url).path.lower() for part in ('accountchooser', 'signinchooser')):
                # An existing Google session may show an account chooser first.
                account = await self.visible(root.locator('[data-identifier]').filter(has_text=item['email']))
                if not account:
                    account = await self.visible(root.get_by_text(item['email'], exact=True))
                other = await self.visible(root.get_by_text(re.compile(r'^Use another account$', re.I)))
                choice = account if account else other
                key = (root, root.url, 'google-account')
                if choice and key not in attempted:
                    attempted.add(key)
                    await choice.click(timeout=3000)
                    self.log(item['row'], 'Google account selected')
                    return
            stay = await self.visible(root.get_by_text(re.compile(r'Stay signed in', re.I)))
            if stay:
                yes = await self.visible(root.get_by_role('button', name=re.compile(r'^(Yes|Yes,? stay signed in|Stay signed in)$', re.I)))
                if not yes:
                    yes = await self.visible(root.locator('input[type="submit"][value="Yes"]'))
                key = (root, root.url, 'stay-yes')
                if yes and await yes.is_enabled() and key not in attempted:
                    await yes.click(timeout=2000)
                    attempted.add(key)
                    self.log(item['row'], 'Stay signed in: Yes')
                continue
            password = await self.visible(root.locator('input[type="password"], input#i0118, input[name="passwd"], input#PasswordPage-PasswordField, input[autocomplete="current-password"]'))
            email = None if password else await self.visible(root.locator('input#identifierId, input[name="identifier"], input[type="email"], input#i0116, input[name="loginfmt"], input[name="username"], input#EmailPage-EmailField'))
            if not password and not email and urlsplit(root.url).hostname == 'accounts.google.com':
                email = await self.visible(root.get_by_role('textbox', name=re.compile(r'Email or phone|Email', re.I)))
            field = password if password else email
            if not field:
                continue
            kind = 'password' if password else 'email'
            key = (root, root.url, kind)
            if key in attempted:
                # Both providers can ask for the ID again at the same URL.
                # Only refill an empty email prompt, once; passwords never retry.
                repeat_key = (root, root.url, 'email-repeated')
                if (kind != 'email'
                        or urlsplit(root.url).hostname not in ('accounts.google.com', 'login.microsoftonline.com')
                        or repeat_key in attempted
                        or await field.input_value(timeout=1500)):
                    continue
                attempted.add(repeat_key)
                attempted.discard(key)
            # Retry fill only if submission never happened; do not repeat login attempts.
            await field.fill(item[kind], timeout=3000)
            if await field.input_value(timeout=1500) != item[kind]:
                raise RuntimeError('Login field did not retain its value')
            submit = None
            if urlsplit(root.url).hostname == 'accounts.google.com':
                submit = await self.visible(root.locator('#passwordNext button, button#passwordNext' if password else '#identifierNext button, button#identifierNext'))
            if not submit:
                submit = await self.visible(root.get_by_role('button', name=re.compile(r'^(Continue|Next|Sign in|Log in)$', re.I)))
            if not submit:
                submit = await self.visible(root.locator('button[type="submit"], input[type="submit"]'))
            if submit and await submit.is_enabled():
                # Mark before click because a navigation can interrupt the response.
                attempted.add(key)
                await submit.click(timeout=3000)
                self.log(item['row'], kind.capitalize() + ' submitted')
            return

    async def editor_ready(self, page):
        if not adobe_url(page.url):
            return False
        for label in (r'^Turn in$', r'^Assign$'):
            button = await self.button(page, label)
            if button and await button.is_enabled():
                return True
        return False

    async def open_remix(self, context, item, wait_seconds=45):
        # Give the viewer time to finish loading before classifying a missing button.
        deadline = time.monotonic() + wait_seconds
        viewer_seen = False
        while time.monotonic() < deadline:
            self.check()
            for page in reversed(context.pages):
                if page.is_closed():
                    continue
                try:
                    # Some templates redirect to sign-in before showing Remix.
                    # Hand that page to the login loop instead of waiting for a viewer.
                    for root in page.frames:
                        if not trusted_login_url(root.url):
                            continue
                        host = urlsplit(root.url).hostname or ''
                        login_host = host in ('accounts.google.com', 'login.microsoftonline.com') or host == 'adobelogin.com' or host.endswith('.adobelogin.com')
                        login_field = await self.visible(root.locator('input#identifierId, input#i0116, input#EmailPage-EmailField, input[type="email"], input[type="password"], input[name="loginfmt"], input[name="username"]'))
                        if login_host or login_field:
                            self.log(item['row'], 'Sign-in page detected before Remix')
                            return
                    if not adobe_url(page.url):
                        continue
                    if await self.editor_ready(page):
                        return
                    for label in (r'^Remix(?:\s+.*)?$', r'^Use this template$'):
                        button = await self.button(page, label)
                        if button and await button.is_enabled():
                            await button.scroll_into_view_if_needed(timeout=1500)
                            await button.click(timeout=3000)
                            self.log(item['row'], 'Remix clicked')
                            return
                    # A visible Share control confirms the public viewer loaded.
                    if await self.button(page, r'^Share$'):
                        viewer_seen = True
                except Stopped:
                    raise
                except Exception:
                    pass
            await self.sleep()
        if viewer_seen:
            raise NoRemix('Remix not available after 45 seconds')
        raise TimeoutError('Template viewer did not finish loading')

    async def warmup_share(self, page, item, state):
        """At most two Share clicks while the editor readiness control is disabled."""
        if state['count'] >= 2 or not adobe_url(page.url):
            return
        marker = None
        for label in (r'^Turn in$', r'^Assign$'):
            candidate = await self.button(page, label)
            if candidate:
                if await candidate.is_enabled():
                    return
                marker = candidate
        # Public viewers also have Share: require an editor-only readiness marker.
        if not marker:
            return
        share = await self.button(page, r'^Share$')
        if not share or not await share.is_enabled():
            return
        self.check()
        state['count'] += 1
        self.log(item['row'], 'Preparing editor: Share click ' + str(state['count']) + '/2')
        try:
            await share.click(timeout=2000)
            await self.sleep(1)
        finally:
            # Dismiss any opened share popover before readiness/final publishing.
            await page.keyboard.press('Escape')
        await self.sleep(1)

    async def ready_login(self, context, item):
        deadline = time.monotonic() + self.timeout
        last_action, attempted = {}, set()
        warmup = {'count': 0}
        manual_shown = False
        while time.monotonic() < deadline:
            self.check()
            for page in reversed(context.pages):
                if page.is_closed():
                    continue
                try:
                    if await self.editor_ready(page):
                        return page
                    await self.warmup_share(page, item, warmup)
                    if await self.editor_ready(page):
                        return page
                    if not trusted_login_url(page.url):
                        if not manual_shown:
                            self.log(item['row'], 'External school SSO/verification: complete in Chrome; waiting')
                            manual_shown = True
                        continue
                    await self.handle_login_fields(page, item, attempted)
                    acknowledge = await self.button(page, r'^I understand[.!]?$')
                    acknowledgement_key = (page, page.url, 'i-understand')
                    if acknowledge and await acknowledge.is_enabled() and acknowledgement_key not in attempted:
                        attempted.add(acknowledgement_key)
                        await acknowledge.click(timeout=3000)
                        self.log(item['row'], 'I understand clicked')
                    if urlsplit(page.url).hostname == 'accounts.google.com':
                        consent = await self.button(page, r'^(Continue|Continue to Adobe)$')
                        stamp = (page, page.url, 'google-continue')
                        if consent and await consent.is_enabled() and stamp not in attempted:
                            attempted.add(stamp)
                            await consent.click(timeout=3000)
                    for label in (r'^(Company or school account|School account)$', r'^Continue to Adobe$', r'^(Not now|Skip)$', r'^Remix(?:\s+.*)?$', r'^Use this template$'):
                        loc = await self.button(page, label)
                        stamp = (page.url, label)
                        if loc and await loc.is_enabled() and time.monotonic() - last_action.get(stamp, 0) > 8:
                            await loc.scroll_into_view_if_needed(timeout=1500)
                            await loc.click(timeout=1500)
                            last_action[stamp] = time.monotonic()
                except Stopped:
                    raise
                except Exception:
                    pass
            await self.sleep()
        raise TimeoutError('Login/editor not ready. Check Chrome for OTP, school SSO or login error.')

    async def copy_once(self, context, page, copy, template):
        """One click, then bounded read polling under a shared clipboard lock."""
        async with self.clipboard_lock:
            origin = urlsplit(page.url)
            if origin.scheme != 'https' or origin.hostname not in ('express.adobe.com', 'new.express.adobe.com'):
                raise RuntimeError('Unexpected clipboard origin')
            await context.grant_permissions(['clipboard-read', 'clipboard-write'], origin=origin.scheme + '://' + origin.netloc)
            await page.bring_to_front()
            # Clearing prevents accepting a stale result belonging to another student.
            await page.evaluate("navigator.clipboard.writeText('')")
            await copy.click(timeout=3000)
            deadline = time.monotonic() + 12
            while time.monotonic() < deadline:
                self.check()
                try:
                    value = await page.evaluate('navigator.clipboard.readText()')
                    if valid_published_link(value, template):
                        return value.strip()
                except Exception:
                    pass
                await self.sleep(.25)
        raise TimeoutError('Copy clicked once, but no new published URL could be read')

    async def published_link(self, context, template):
        deadline = time.monotonic() + 90
        while time.monotonic() < deadline:
            self.check()
            for page in reversed(context.pages):
                if page.is_closed() or not adobe_url(page.url):
                    continue
                try:
                    dialogs = page.get_by_role('dialog')
                    roots = [dialogs.nth(i) for i in range(await dialogs.count()) if await dialogs.nth(i).is_visible()]
                    copy = await self.button(page, r'^Copy link$')
                    if not roots and copy:
                        roots = [page]
                    candidates = set()
                    for root in roots:
                        for selector, attr in (('input', 'value'), ('textarea', 'value'), ('a[href]', 'href')):
                            locs = root.locator(selector)
                            for i in range(await locs.count()):
                                loc = locs.nth(i)
                                if not await loc.is_visible():
                                    continue
                                value = await loc.input_value() if attr == 'value' else await loc.get_attribute(attr)
                                if valid_published_link(value, template):
                                    candidates.add(value.strip())
                    if len(candidates) == 1:
                        return candidates.pop()
                except Stopped:
                    raise
                except Exception:
                    continue
                # Keep this outside the retry handler: a failed copy must never loop.
                if copy and await copy.is_enabled():
                    return await self.copy_once(context, page, copy, template)
            await self.sleep()
        raise TimeoutError('Published URL not found; no template/editor link was saved.')

    async def ensure_published(self, context, item, results):
        """Reuse an existing publication, or request creation once."""
        deadline = time.monotonic() + 60
        while time.monotonic() < deadline:
            self.check()
            for page in reversed(context.pages):
                if page.is_closed() or not adobe_url(page.url):
                    continue
                copy = await self.button(page, r'^Copy link$')
                if copy and await copy.is_enabled():
                    self.log(item['row'], 'Published link already available')
                    return
                create = await self.button(page, r'^Create link$')
                if create and await create.is_enabled():
                    results.save(item, 'Running', 'Create link requested')
                    await create.click(timeout=3000)
                    return
            await self.sleep()
        raise TimeoutError('Publish panel has neither Copy link nor Create link')

    async def run(self, source):
        from playwright.async_api import async_playwright
        headers, values, rows = read_rows(source)
        results = Results(source, headers, values, self.events)
        results.export()  # Detect locked output file before launching accounts.
        sem = asyncio.Semaphore(self.parallel)
        async with async_playwright() as pw:
            browser = await pw.chromium.launch(channel='chrome', headless=False, args=['--start-maximized'])
            async def worker(item):
                async with sem:
                    while self.pause is not None and self.pause.is_set():
                        await self.sleep(.3)
                    self.check()
                    old = results.previous(item)
                    if self.retry_failed and old.get('status') not in ('Failed','Stopped'):
                        self.events.put(('progress',1))
                        return
                    if old.get('status') == 'Done' and adobe_url(old.get('link', '')):
                        self.log(item['row'], 'Already completed; skipped')
                        self.events.put(('progress',1))
                        return
                    if old.get('stage') in ('Create link requested', 'Capture link', 'Publish ambiguous'):
                        self.log(item['row'], 'Review previous publication before retry; clear this row in progress JSON only after checking')
                        self.events.put(('progress',1))
                        return
                    context = await browser.new_context(no_viewport=True)
                    for origin in ('https://new.express.adobe.com', 'https://express.adobe.com'):
                        await context.grant_permissions(['clipboard-read', 'clipboard-write'], origin=origin)
                    stage = 'Open template'
                    link = ''
                    try:
                        self.log(item['row'], stage)
                        results.save(item, 'Running', stage)
                        page = await context.new_page()
                        await page.goto(item['template'], wait_until='domcontentloaded', timeout=60000)
                        # Fixed emulated viewports can extend beyond Windows display scaling.
                        await page.keyboard.press('Control+0')
                        stage = 'Check Remix'
                        self.log(item['row'], stage)
                        await self.open_remix(context, item)
                        stage = 'Login / Wait for Turn in or Assign'
                        self.log(item['row'], stage)
                        page = await self.ready_login(context, item)
                        stage = 'Share'
                        self.log(item['row'], stage)
                        await self.click(context, r'^Share$')
                        stage = 'Publish'
                        await self.click(context, r'^Publish(?: to web)?$')
                        stage = 'Create link requested'
                        # Durable checkpoint before the irreversible click; never blindly retry publishing.
                        await self.ensure_published(context, item, results)
                        stage = 'Capture link'
                        self.log(item['row'], stage)
                        link = await self.published_link(context, item['template'])
                        results.save(item, 'Done', 'Complete', link)
                        self.log(item['row'], 'Done — link saved')
                    except NoRemix:
                        results.save(item, 'Skipped', 'Remix not available')
                        self.log(item['row'], 'Skipped — Remix not available')
                    except Stopped:
                        results.save(item, 'Stopped', stage, link)
                        raise
                    except Exception as exc:
                        # Do not log exception details: they may contain credentials or page content.
                        status = 'Review' if stage in ('Create link requested', 'Capture link') else 'Failed'
                        results.save(item, status, stage, link)
                        self.log(item['row'], f'{status} at {stage} ({type(exc).__name__}); check input/progress file')
                    finally:
                        await context.close()
                        self.events.put(('progress', 1))
            tasks = [asyncio.create_task(worker(item)) for item in rows]
            try:
                while not all(t.done() for t in tasks):
                    if self.stop.is_set():
                        for task in tasks:
                            task.cancel()
                        break
                    await asyncio.sleep(.3)
                outcomes = await asyncio.gather(*tasks, return_exceptions=True)
                for outcome in outcomes:
                    if isinstance(outcome, Exception) and not isinstance(outcome, Stopped):
                        self.events.put(('log', 'Worker stopped unexpectedly: ' + type(outcome).__name__))
            finally:
                await browser.close()
        self.events.put(('log', 'Stopped' if self.stop.is_set() else 'Batch finished. Check Status column.'))
        self.events.put(('log', 'Output: ' + str(results.target)))


def personalized_greeting(name):
    cleaned = ' '.join(name.split())
    if not cleaned or len(cleaned) > 50:
        raise ValueError('Please enter a name between 1 and 50 characters.')
    if cleaned.casefold() in {'aryan', 'aryan malik'}:
        return cleaned, 'Welcome back, Admin Aryan!'
    return cleaned, 'Welcome, ' + cleaned + '!'


class App:
    def __init__(self):
        import sys
        from ui_glass import GlassApp
        self.ui = GlassApp(sys.modules[__name__])

    def run(self):
        self.ui.run()


if __name__ == '__main__':
    App().run()
